@code {
    // ── Common emoji set for the picker ──
    private static readonly string[] _commonEmojis = ["👍", "❤️", "😂", "🎉", "😮", "🚀"];

    // ── Channel state ──
    private List<Channel>? _channels;
    private int _activeChannelId;
    private Channel? _activeChannel;

    // ── Message state ──
    private List<Message>? _messages;
    private string _newMessageText = "";
    private int? _hoveredMessageId;
    private int? _emojiPickerMessageId;
    private bool _loadingMore;
    private bool _allMessagesLoaded;
    private const int PageSize = 30;
    private ElementReference _messageListRef;

    // ── Thread state ──
    private bool _threadOpen;
    private Message? _threadRootMessage;
    private List<Message>? _threadMessages;
    private string _threadReplyText = "";

    // ── Thread summaries (keyed by root message id) ──
    private Dictionary<int, int> _replyCounts = new();

    protected override async Task OnInitializedAsync()
    {
        _channels = await ChatService.GetChannelsAsync();
    }

    // ── Channel selection ──
    private async Task SelectChannelAsync(Channel channel)
    {
        _activeChannelId = channel.Id;
        _activeChannel = channel;
        _allMessagesLoaded = false;
        _messages = await ChatService.GetMessagesAsync(channel.Id, 0, PageSize);
        _replyCounts = BuildReplyCounts(_messages);

        await ChatService.MarkChannelReadAsync(channel.Id);

        // Refresh channels to clear unread badge
        _channels = await ChatService.GetChannelsAsync();

        CloseThread();

        await ScrollToBottom();
    }

    // ── Sending a message ──
    private async Task SendMessageAsync()
    {
        if (string.IsNullOrWhiteSpace(_newMessageText) || _activeChannel is null) return;

        var sent = await ChatService.SendMessageAsync(_activeChannel.Id, _newMessageText.Trim(), null);
        _messages ??= new();
        _messages.Add(sent);
        _newMessageText = "";

        await ScrollToBottom();
    }

    private async Task OnMessageKeyDown(KeyboardEventArgs e)
    {
        if (e is { Key: "Enter", ShiftKey: false })
        {
            await SendMessageAsync();
        }
    }

    // ── Scroll-to-top pagination ──
    private async Task OnMessageListScroll()
    {
        if (_loadingMore || _allMessagesLoaded || _messages is null || _activeChannel is null) return;

        var scrollTop = await JS.InvokeAsync<double>("eval", "document.querySelector('[blazor\\\\:elementReference]')?.scrollTop ?? 1");
        if (scrollTop > 50) return;

        _loadingMore = true;
        StateHasChanged();

        var older = await ChatService.GetMessagesAsync(_activeChannel.Id, _messages.Count, PageSize);
        if (older.Count == 0)
        {
            _allMessagesLoaded = true;
        }
        else
        {
            _messages.InsertRange(0, older);
            var additionalCounts = BuildReplyCounts(older);
            foreach (var kvp in additionalCounts)
            {
                _replyCounts.TryAdd(kvp.Key, kvp.Value);
            }
        }

        _loadingMore = false;
    }

    // ── Reactions ──
    private void ToggleEmojiPicker(int messageId)
    {
        _emojiPickerMessageId = _emojiPickerMessageId == messageId ? null : messageId;
    }

    private async Task AddReactionAsync(int messageId, string emoji)
    {
        _emojiPickerMessageId = null;
        await ChatService.AddReactionAsync(messageId, emoji);

        // Refresh messages to reflect updated reactions
        if (_activeChannel is not null)
        {
            _messages = await ChatService.GetMessagesAsync(_activeChannel.Id, 0, _messages?.Count ?? PageSize);
        }

        // Refresh thread if open
        if (_threadOpen && _threadRootMessage is not null)
        {
            _threadMessages = await ChatService.GetThreadAsync(_threadRootMessage.Id);
        }
    }

    // ── Thread ──
    private async Task OpenThreadAsync(Message rootMessage)
    {
        _threadRootMessage = rootMessage;
        _threadMessages = await ChatService.GetThreadAsync(rootMessage.Id);
        _threadReplyText = "";
        _threadOpen = true;
    }

    private void CloseThread()
    {
        _threadOpen = false;
        _threadRootMessage = null;
        _threadMessages = null;
        _threadReplyText = "";
    }

    private async Task SendThreadReplyAsync()
    {
        if (string.IsNullOrWhiteSpace(_threadReplyText) || _threadRootMessage is null || _activeChannel is null) return;

        await ChatService.SendMessageAsync(_activeChannel.Id, _threadReplyText.Trim(), _threadRootMessage.Id);
        _threadMessages = await ChatService.GetThreadAsync(_threadRootMessage.Id);
        _threadReplyText = "";

        // Update reply count in main view
        _replyCounts[_threadRootMessage.Id] = _threadMessages.Count;
    }

    private async Task OnThreadKeyDown(KeyboardEventArgs e)
    {
        if (e is { Key: "Enter", ShiftKey: false })
        {
            await SendThreadReplyAsync();
        }
    }

    // ── Helpers ──
    private int GetReplyCount(int messageId) =>
        _replyCounts.TryGetValue(messageId, out var count) ? count : 0;

    private static Dictionary<int, int> BuildReplyCounts(List<Message> messages)
    {
        var counts = new Dictionary<int, int>();
        foreach (var m in messages)
        {
            if (m.ReplyToId is int rootId)
            {
                counts[rootId] = counts.TryGetValue(rootId, out var c) ? c + 1 : 1;
            }
        }
        return counts;
    }

    private static string TruncateDescription(string description) =>
        description.Length > 40 ? string.Concat(description.AsSpan(0, 37), "...") : description;

    private static string FormatRelativeTime(DateTime sentAt)
    {
        var diff = DateTime.UtcNow - sentAt.ToUniversalTime();
        return diff.TotalSeconds switch
        {
            < 60 => "just now",
            < 3600 => $"{(int)diff.TotalMinutes} min ago",
            < 86400 => $"{(int)diff.TotalHours}h ago",
            < 604800 => $"{(int)diff.TotalDays}d ago",
            _ => sentAt.ToString("MMM d, yyyy")
        };
    }

    private async Task ScrollToBottom()
    {
        await Task.Yield();
        await JS.InvokeVoidAsync("eval",
            "setTimeout(() => { let el = document.querySelector('.message-list'); if(el) el.scrollTop = el.scrollHeight; }, 50)");
    }
}

